// Des: Dispatch each za command to its code
// Flo: read argv > parse ladder flags > build Ctx > call the command > exit code
// I/O: process Init (main) > u8 exit code 0-4; text on stdout
// ===================================================================
const std = @import("std"); const targ = @import("ct-ctrl-args.zig"); const ctxz = @import("ct-ctrl-ctxz.zig"); const stat = @import("ct-comm-stat.zig"); const halt = @import("ct-comm-halt.zig"); const logi = @import("ct-comm-logi.zig"); const runz = @import("ct-comm-runz.zig"); const prob = @import("ct-comm-prob.zig"); const flw = @import("ct-comm-flow.zig"); const setu = @import("ct-comm-setu.zig"); const expo = @import("ct-comm-expo.zig"); const feed = @import("ct-comm-feed.zig"); const matx = @import("ct-comm-matx.zig"); const flws = @import("ct-comm-flws.zig"); const acc = @import("ct-comm-acct.zig"); const acctm = @import("ru-acct-main.zig"); const conf = @import("cf-conf-load.zig"); const lck = @import("st-lock-main.zig"); const erro = @import("er-erro-type.zig"); const envl = @import("ct-ctrl-envl.zig");
pub const HELP = "za: works Zalo Web for you at a human pace\n  za status [--json]            ready or halted, caps used\n  za caps [--json]              sends left this hour and today\n  za login                      open Zalo, scan the QR once\n  za secret                     list the accounts in user-acct.json (id, label, masked phone); no passwords exist\n  --acct <id>|all               pick one account (own browser profile, scan its QR once) or run all, one at a time\n  za run <job> [words] [flags]  jobs: read reply summ say send remind pin mute group forward react quote recall delete pinmsg download archive hide unread alias block sticker file poll note label quick usequick friend accept ignore reqaccept reqignore rename addmember delmember deputy leave unfriend logout devices devout notify lang storage help feedback passwd profile cloud canary\n  za pause | stop | resume      stop all jobs at the next action, or let them go again\n  za log [--json]               last 20 activity rows\n  za probe <name>               save a redacted dump of the page (label discovery)\n  za plan '<item>' ...          make a flow, print the one approval list\n  za approve all|<ids>          approve risky items once\n  za go [--live]                run the flow by itself; waits only when Zalo needs you\n  za flow list | run <name>     named routines from flow_list\n  za watch [--live]             check the inbox at a human cadence in work sessions\n  za setup [--yes]              check browser + folders, accept the Zalo risk once\n  za matrix [--json]            every job and its quality level\n  za flows [--json]             every Zalo Web action: built, gap, hand (yours) or out\n  za feed [--live]              stored messages of the chats in feed_chat_list as JSONL for scra (dry-run counts only)\n  za export | report | backup   your data as JSONL · support bundle · copy of the database\n  za retry <id> | undo last     run a parked item again · recall the last message (--live --force)\n  za purge                      delete messages older than msgs_keep_days\nflags: --read (look only) · --dry (default: preview, change nothing) · --live (act) · --live --force (bulk, group, forward) · --json · --mock · --conf <file>\nexit: 0 ok · 1 fail · 2 usage · 3 finding · 4 blocked\n";
const KEEP = [_][]const u8{ "help", "secret", "matrix", "flows" };
const BROW = [_][]const u8{ "run", "login", "probe", "go", "watch", "flow", "retry", "undo" };
const AllSt = struct { init: std.process.Init, args: targ.Args };
fn say(px: ?*anyopaque, msg: []const u8) void { const st: *AllSt = @ptrCast(@alignCast(px.?)); const line = std.fmt.allocPrint(st.init.arena.allocator(), "{s}\n", .{msg}) catch return; if (st.args.sink) |snk| { snk.appendSlice(st.init.arena.allocator(), line) catch {}; return; } std.Io.File.stdout().writeStreamingAll(st.init.io, line) catch {}; }
fn runner(px: ?*anyopaque, id: []const u8) anyerror!u8 { const st: *AllSt = @ptrCast(@alignCast(px.?)); var one = st.args; one.acct = id; return dispatch(st.init, one) catch |err| { const mesg = erro.mesgAny(err); std.debug.print("error: {s} - {s}\nfix: {s}\n", .{ mesg.what, mesg.whyz, mesg.fixz }); return err; }; }
fn dispatch(init: std.process.Init, args: targ.Args) !u8 { var ctx = try ctxz.make(init, args); if (std.mem.eql(u8, args.cmd, "secret")) return acc.secretRun(&ctx); if (std.mem.eql(u8, args.cmd, "help")) { try ctxz.emit(&ctx, HELP); return 0; } if (std.mem.eql(u8, args.cmd, "status")) return stat.statRun(&ctx); if (std.mem.eql(u8, args.cmd, "caps")) return stat.capsRun(&ctx); if (std.mem.eql(u8, args.cmd, "log")) return halt.logRun(&ctx); if (std.mem.eql(u8, args.cmd, "pause")) return halt.pauseRun(&ctx, "paused by owner"); if (std.mem.eql(u8, args.cmd, "stop")) return halt.pauseRun(&ctx, "stopped by owner"); if (std.mem.eql(u8, args.cmd, "resume")) return halt.resumeRun(&ctx); if (std.mem.eql(u8, args.cmd, "purge")) return halt.purgeRun(&ctx); if (std.mem.eql(u8, args.cmd, "login")) return logi.loginRun(&ctx); if (std.mem.eql(u8, args.cmd, "run")) return runz.runRun(&ctx); if (std.mem.eql(u8, args.cmd, "probe")) return prob.probeRun(&ctx); if (std.mem.eql(u8, args.cmd, "plan")) return flw.planRun(&ctx); if (std.mem.eql(u8, args.cmd, "setup")) return setu.setupRun(&ctx); if (std.mem.eql(u8, args.cmd, "matrix")) return matx.matxRun(&ctx); if (std.mem.eql(u8, args.cmd, "flows")) return flws.flwsRun(&ctx); if (std.mem.eql(u8, args.cmd, "export")) return expo.exportRun(&ctx); if (std.mem.eql(u8, args.cmd, "feed")) return feed.feedRun(&ctx); if (std.mem.eql(u8, args.cmd, "report")) return expo.reportRun(&ctx); if (std.mem.eql(u8, args.cmd, "backup")) return expo.backupRun(&ctx); if (std.mem.eql(u8, args.cmd, "retry")) return expo.retryRun(&ctx); if (std.mem.eql(u8, args.cmd, "undo")) return expo.undoRun(&ctx); if (std.mem.eql(u8, args.cmd, "approve")) return flw.approveRun(&ctx); if (std.mem.eql(u8, args.cmd, "go")) return flw.goRun(&ctx); if (std.mem.eql(u8, args.cmd, "watch")) return flw.watchRun(&ctx); if (std.mem.eql(u8, args.cmd, "flow")) return flw.flowRun(&ctx); std.debug.print("usage error: unknown command {s}\n", .{args.cmd}); return error.BadUsage; }
fn allRun(init: std.process.Init, args: targ.Args) !u8 { const allo = init.arena.allocator(); var base = args; base.acct = ""; var ctx = try ctxz.make(init, base); var brow = false; for (BROW) |nm| { if (std.mem.eql(u8, nm, args.cmd)) brow = true; } const home = init.environ_map.get("USERPROFILE") orelse init.environ_map.get("HOME") orelse "."; const root = try conf.pathHome(allo, home, conf.dataRoot(ctx.cfg, @import("builtin").os.tag == .windows)); var ids: std.ArrayList([]const u8) = .empty; for (ctx.book.accs) |ac| try ids.append(allo, ac.id);
var gl: ?[]const u8 = null; defer if (gl) |lp| lck.release(init.io, lp); if (brow) { const gdir = try std.fs.path.join(allo, &.{ root, "acct" }); try std.Io.Dir.cwd().createDirPath(init.io, gdir); const lp = try std.fs.path.join(allo, &.{ gdir, "za.lock" }); try lck.acquire(allo, init.io, lp, lck.pidSelf(), ctxz.nowMs(&ctx)); gl = lp; }
var sb: [8]u8 = undefined; init.io.random(&sb); var rng = std.Random.DefaultPrng.init(std.mem.readInt(u64, &sb, .little)); var st: AllSt = .{ .init = init, .args = args }; var env: acctm.Env = .{ .aren = allo, .iozz = init.io, .cfg = ctx.cfg, .root = root, .ids = ids.items, .now = ctxz.nowMs(&ctx), .rng = &rng, .ctx = &st, .run = runner, .say = say, .browser = brow }; const res = try acctm.runAll(&env); for (res) |rs| try ctxz.emitf(&ctx, "account {s}: {s}\n", .{ rs.id, rs.state }); return acctm.worst(res); }
fn writes(args: targ.Args) bool { for ([_][]const u8{ "run", "send", "go", "watch", "flow", "retry", "undo", "purge", "feed", "export", "backup", "plan", "approve" }) |nam| { if (std.mem.eql(u8, nam, args.cmd)) return true; } return false; }
fn failJ(init: std.process.Init, args: targ.Args, jsnz: bool, err: anyerror) u8 { const mesg = erro.mesgAny(err); std.debug.print("error: {s} - {s}\nfix: {s}\n", .{ mesg.what, mesg.whyz, mesg.fixz }); const code = erro.exitCode(err); if (jsnz) { const allo = init.arena.allocator(); const text = std.fmt.allocPrint(allo, "{s} - {s}; fix: {s}", .{ mesg.what, mesg.whyz, mesg.fixz }) catch return code; const docz = envl.failDoc(allo, args.cmd, code, @errorName(err), text, if (writes(args)) args.mode == .dry or args.mode == .read else null) catch return code; std.Io.File.stdout().writeStreamingAll(init.io, std.fmt.allocPrint(allo, "{s}\n", .{docz}) catch return code) catch {}; } return code; }
fn runCore(init: std.process.Init, args: targ.Args) !u8 { if (args.bare and !args.helz) { std.debug.print("{s}\n", .{HELP}); return 2; } if (args.helz) { if (args.sink) |snk| { try snk.appendSlice(init.arena.allocator(), HELP ++ "\n"); } else try std.Io.File.stdout().writeStreamingAll(init.io, HELP ++ "\n"); return 0; } if (!std.mem.eql(u8, args.acct, "all")) return dispatch(init, args); for (KEEP) |nm| { if (std.mem.eql(u8, nm, args.cmd)) { var one = args; one.acct = ""; return dispatch(init, one); } } return allRun(init, args); }
pub fn runMain(init: std.process.Init) !u8 { const allo = init.arena.allocator(); var iter = try init.minimal.args.iterateAllocator(allo); _ = iter.next(); var argv: std.ArrayList([]const u8) = .empty; while (iter.next()) |item| try argv.append(allo, item); var jsnz = false; for (argv.items) |item| { if (std.mem.eql(u8, item, "--json")) jsnz = true; } var args = targ.parse(allo, argv.items) catch |err| return failJ(init, .{ .cmd = "" }, jsnz, err); var sink: std.ArrayList(u8) = .empty; if (jsnz) args.sink = &sink; const code = runCore(init, args) catch |err| return failJ(init, args, jsnz, err); if (jsnz) { const docz = try envl.okayDoc(allo, if (args.bare) "help" else args.cmd, code, sink.items, if (writes(args)) args.mode == .dry or args.mode == .read else null); try std.Io.File.stdout().writeStreamingAll(init.io, try std.fmt.allocPrint(allo, "{s}\n", .{docz})); } return code; }
